# A simple two-stage guardrail wrapper around a model call

def input_guard(user_input):
    if len(user_input) > 5000:
        return False, "Input too long"
    if contains_injection_pattern(user_input):
        return False, "Possible prompt injection"
    if hate_speech_detector(user_input):
        return False, "Policy violation"
    return True, None

def output_guard(response):
    response = redact_pii(response)          # remove leaked personal data
    response = redact_secrets(response)        # remove API keys / tokens
    if dangerous_content(response):
        return "I can't help with that."       # block unsafe output
    return response

def safe_chat(user_input):
    ok, reason = input_guard(user_input)       # STAGE 1: input
    if not ok:
        return f"Blocked: {reason}"
    raw = model.generate(user_input)
    return output_guard(raw)                    # STAGE 2: output
